def main():
    path = ROOT / "worklist/document_viewer_server.py"
    text = path.read_text()
    if NEW in text:
        print("Reference comparison fix already installed. Restart the viewer.")
        return
    if text.count(OLD) != 1:
        raise RuntimeError("Verification block differs; no changes made")
    updated = text.replace(OLD, NEW, 1)
    ast.parse(updated)
    checkpoint = ROOT / "checkpoints" / ("portal-reference-fix-" + datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ"))
    checkpoint.mkdir(parents=True)
    shutil.copy2(path, checkpoint / path.name)
    path.write_text(updated)
    print("PASS: exact local patient-reference comparison fixed.")
    print("Backup:", checkpoint)
    print("Restart the viewer and run signed-in verification again.")

if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        print("STOP:", str(error))
        sys.exit(1)
